// Référence, échéance légale (1 mois, art. 12.3 du RGPD), droits reconnus par l'IA.
const f = $('Exercer vos droits').first().json;
const ia = $('Reconnaître la demande').first().json.output;
const maintenant = $now.setZone('Europe/Paris');
const LIBELLES = { acces: 'accès', rectification: 'rectification', effacement: 'effacement', opposition: 'opposition', portabilite: 'portabilité', limitation: 'limitation' };
const droits = [...new Set((ia.droits ?? []).filter(d => LIBELLES[d]))];
return [{ json: { reference: 'RGPD-' + maintenant.toFormat('yyyyLLdd-HHmmss'), nom: String(f.nom ?? '').trim(), email: String(f.email ?? '').trim().toLowerCase(),
  message: f.message, est_rgpd: !!ia.est_demande_rgpd && droits.length > 0, droits, droits_lisibles: droits.map(d => LIBELLES[d]).join(', '),
  precisions: ia.precisions ?? '', recue_le: maintenant.toISO(), echeance: maintenant.plus({ months: 1 }).toISODate(),
  echeance_lisible: maintenant.plus({ months: 1 }).setLocale('fr').toFormat('d LLLL yyyy') } }];

