// Ce que chaque outil contient sur la personne, et l'action prévue selon les droits exercés.
const d = $('Préparer la demande').first().json;
const lignes = n => $(n).all().map(i => i.json).filter(r => r && r.id != null);
const nettoyer = r => Object.fromEntries(Object.entries(r).filter(([k]) => !['id', 'createdAt', 'updatedAt'].includes(k)));
const veut = x => d.droits.includes(x);
const outils = [
  { outil: 'CRM (prospects)', cle: 'crm', donnees: lignes('Chercher dans le CRM'),
    action: veut('effacement') || veut('opposition') ? 'supprimer' : 'aucune', motif: veut('effacement') ? 'effacement demandé' : veut('opposition') ? 'opposition à la prospection' : '' },
  { outil: 'Newsletter', cle: 'newsletter', donnees: lignes('Chercher dans la newsletter'),
    action: veut('effacement') || veut('opposition') ? 'supprimer' : 'aucune', motif: veut('effacement') ? 'effacement demandé' : veut('opposition') ? 'opposition (désinscription)' : '' },
  { outil: 'Facturation (avoirs)', cle: 'facturation', donnees: lignes('Chercher dans la facturation'),
    action: veut('effacement') ? 'conserver' : 'aucune', motif: veut('effacement') ? 'obligation légale : pièces comptables conservées 10 ans (art. L123-22 du Code de commerce)' : '' },
].map(o => ({ ...o, nombre: o.donnees.length, donnees: o.donnees.map(nettoyer), action: o.donnees.length ? o.action : 'aucune' }));
const export_ = { reference: d.reference, personne: { nom: d.nom, email: d.email }, genere_le: $now.toISO(),
  donnees: Object.fromEntries(outils.map(o => [o.outil, o.donnees])) };
const fichier = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(export_, null, 2), 'utf8'), 'mes-donnees-' + d.reference + '.json', 'application/json');
return [{ json: { outils, total: outils.reduce((s, o) => s + o.nombre, 0), suppressions: outils.filter(o => o.action === 'supprimer').map(o => o.cle),
  export_joint: veut('acces') || veut('portabilite'), rectification: veut('rectification') || veut('limitation') }, binary: { export: fichier } }];

// Récupère l'export (copie des données) pour la pièce jointe, seulement si l'accès ou la portabilité est demandé.
const inv = $('Inventaire des données').first();
return [{ json: { joindre: inv.json.export_joint }, binary: inv.json.export_joint ? { export: inv.binary.export } : {} }];

// Demandes non closes dont l'échéance légale tombe dans les 7 jours (ou est dépassée).
const ref = ($('Vérifier les échéances (test)').isExecuted && $('Vérifier les échéances (test)').first().json.date) ? DateTime.fromISO($('Vérifier les échéances (test)').first().json.date) : $now.setZone('Europe/Paris');
const urgentes = $input.all().map(i => i.json).filter(r => r && r.reference && !String(r.statut).startsWith('close'))
  .map(r => ({ ...r, jours: Math.ceil(DateTime.fromISO(String(r.echeance)).diff(ref.startOf('day'), 'days').days) })).filter(r => r.jours <= 7);
return urgentes.length ? [{ json: { urgentes, reference: ref.toISODate() } }] : [];
